class CountIntervals {
private:
    map<int, int> intervals;
    long long total;
public:
    CountIntervals() : total(0) {

    }

    void add(int left, int right) {
        auto it = intervals.upper_bound(left);
        if (it != intervals.begin()) {
            auto pit = it;
            --pit;
            if (pit->second >= left - 1) {
                left = min(left, pit->first);
                right = max(right, pit->second);
                total -= (long long)(pit->second - pit->first + 1);
                intervals.erase(pit);
            }
        }
        while (it != intervals.end() && it->first <= right + 1) {
            right = max(right, it->second);
            total -= (long long)(it->second - it->first + 1);
            it = intervals.erase(it);
        }
        intervals[left] = right;
        total += (long long)(right - left + 1);
    }

    int count() {
        return (int)total;
    }
};
